// Parse incoming Telegram message for Chef Bot
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const message = data.message || data.callback_query?.message;
  const callbackQuery = data.callback_query;

  if (!message && !callbackQuery) {
    continue;
  }

  const text = data.message?.text || callbackQuery?.data || '';
  const chatId = message?.chat?.id;
  const userId = data.message?.from?.id || callbackQuery?.from?.id;
  const username = data.message?.from?.username || callbackQuery?.from?.username;
  const firstName = data.message?.from?.first_name || callbackQuery?.from?.first_name;
  const lastName = data.message?.from?.last_name || callbackQuery?.from?.last_name;

  // Parse command and parameters
  let command = '';
  let params = {};

  if (text.startsWith('/')) {
    const parts = text.split(' ');
    command = parts[0].substring(1).toLowerCase();

    // Parse parameters based on command
    switch(command) {
      case 'buscar':
        // /buscar pollo arroz tomate -> ingredients: ['pollo', 'arroz', 'tomate']
        const ingredients = parts.slice(1).filter(p => p.trim());
        params = {
          ingredients: ingredients.slice(0, 3) // Máximo 3 ingredientes
        };
        break;

      case 'receta':
        // /receta 52940 -> recipeId: '52940'
        params = {
          recipeId: parts[1] || null
        };
        break;

      case 'favorito':
        // /favorito 52940 Chicken Curry -> recipeId, recipeName
        params = {
          recipeId: parts[1] || null,
          recipeName: parts.slice(2).join(' ') || null
        };
        break;

      case 'eliminar_favorito':
        params = {
          recipeId: parts[1] || null
        };
        break;

      case 'filtro':
        // /filtro vegetarian
        const validFilters = ['none', 'vegetarian', 'vegan', 'gluten_free'];
        const filter = parts[1]?.toLowerCase();
        params = {
          filter: validFilters.includes(filter) ? filter : null,
          showOptions: !filter
        };
        break;

      case 'convertir':
        // /convertir 2 tazas a ml
        const amount = parseFloat(parts[1]);
        const fromUnit = parts[2];
        const toUnit = parts[4] || parts[3]; // handle 'a' word
        params = {
          amount: isNaN(amount) ? null : amount,
          fromUnit: fromUnit,
          toUnit: toUnit
        };
        break;

      case 'paso':
        // /paso 3 -> stepNumber: 3
        params = {
          stepNumber: parseInt(parts[1]) || null
        };
        break;

      default:
        // No params needed for start, favoritos, recomendar, ayuda
        break;
    }
  } else {
    // Natural language - treat as search query
    command = 'natural';
    params = { text: text };
  }

  results.push({
    json: {
      command,
      params,
      chatId,
      userId,
      username,
      firstName,
      lastName,
      originalText: text,
      isCallback: !!callbackQuery,
      callbackId: callbackQuery?.id,
      timestamp: new Date().toISOString()
    }
  });
}

return results;

// Generate welcome message for Chef Bot
const firstName = $input.first().json.firstName || 'Chef';
const userId = $input.first().json.userId;
const chatId = $input.first().json.chatId;

const welcomeMessage = `🍳 ¡Hola ${firstName}! Bienvenido a **Chef Bot**

Soy tu asistente culinario personal. Puedo ayudarte a:

🔍 Encontrar recetas por ingredientes
⭐ Guardar tus recetas favoritas
🥗 Filtrar por preferencias dietéticas
📏 Convertir medidas de cocina
💡 Darte recomendaciones personalizadas

**Comandos Disponibles:**

🔍 /buscar [ingredientes] - Buscar recetas
   Ejemplo: /buscar pollo arroz

⭐ /favoritos - Ver tus recetas guardadas
🍽 /recomendar - Obtener recomendaciones
🥗 /filtro - Cambiar filtro dietético
📏 /convertir - Convertir medidas
❓ /ayuda - Ver ayuda detallada

¿Qué te gustaría cocinar hoy? 👨‍🍳`;

const keyboard = {
  inline_keyboard: [
    [
      { text: '🔍 Buscar Receta', callback_data: '/ayuda' },
      { text: '🍽 Recomendaciones', callback_data: '/recomendar' }
    ],
    [
      { text: '⭐ Mis Favoritos', callback_data: '/favoritos' },
      { text: '🥗 Filtro Dietético', callback_data: '/filtro' }
    ],
    [
      { text: '❓ Ayuda', callback_data: '/ayuda' }
    ]
  ]
};

return [{
  json: {
    chatId: chatId,
    userId: userId,
    message: welcomeMessage,
    keyboard: keyboard
  }
}];

// Validate search parameters
const params = $input.first().json.params;
const chatId = $input.first().json.chatId;
const userId = $input.first().json.userId;

if (!params.ingredients || params.ingredients.length === 0) {
  return [{
    json: {
      valid: false,
      chatId: chatId,
      message: '❌ Por favor indica al menos un ingrediente\n\n**Uso:** /buscar [ingrediente1] [ingrediente2] [ingrediente3]\n\n**Ejemplos:**\n• /buscar pollo\n• /buscar pollo arroz\n• /buscar tomate cebolla ajo\n\n💡 Puedes buscar hasta 3 ingredientes'
    }
  }];
}

if (params.ingredients.length > 3) {
  return [{
    json: {
      valid: false,
      chatId: chatId,
      message: '❌ Máximo 3 ingredientes permitidos\n\nIngredientes recibidos: ' + params.ingredients.join(', ') + '\n\n💡 Intenta con menos ingredientes para mejores resultados'
    }
  }];
}

return [{
  json: {
    valid: true,
    chatId: chatId,
    userId: userId,
    ingredients: params.ingredients
  }
}];

// Format search results
const response = $input.first().json;
const chatId = $('Validate Search').item.json.chatId;
const ingredients = $('Validate Search').item.json.ingredients;

if (response.error || !response.recipes) {
  return [{
    json: {
      chatId: chatId,
      message: `❌ Error al buscar recetas\n\n${response.error || response.detail || 'Error desconocido'}\n\nPor favor intenta nuevamente.`
    }
  }];
}

const recipes = response.recipes || [];

if (recipes.length === 0) {
  return [{
    json: {
      chatId: chatId,
      message: `🔍 **Búsqueda:** ${ingredients.join(', ')}\n\n😕 No encontré recetas con esos ingredientes\n\n💡 **Sugerencias:**\n• Intenta con ingredientes más comunes\n• Usa nombres en inglés (chicken, rice, tomato)\n• Busca con menos ingredientes`,
      keyboard: {
        inline_keyboard: [
          [
            { text: '🍽 Ver Recomendaciones', callback_data: '/recomendar' },
            { text: '🏠 Menú Principal', callback_data: '/start' }
          ]
        ]
      }
    }
  }];
}

let message = `🍳 **Recetas encontradas (${recipes.length})**\n`;
message += `🔍 Ingredientes: ${ingredients.join(', ')}\n\n`;

recipes.slice(0, 5).forEach((recipe, index) => {
  message += `${index + 1}. **${recipe.name}**\n`;
  message += `   🏷 ${recipe.category} | 🌍 ${recipe.area}\n`;
  message += `   🆔 ID: ${recipe.id}\n\n`;
});

if (recipes.length > 5) {
  message += `\n... y ${recipes.length - 5} recetas más\n`;
}

message += `\n💡 Usa /receta [ID] para ver detalles\n`;
message += `Ejemplo: /receta ${recipes[0].id}`;

// Build inline keyboard with recipe buttons
const recipeButtons = recipes.slice(0, 3).map(r => ({
  text: `📖 ${r.name.substring(0, 20)}...`,
  callback_data: `/receta ${r.id}`
}));

const keyboard = {
  inline_keyboard: [
    recipeButtons.slice(0, 2),
    [
      { text: '🔍 Nueva Búsqueda', callback_data: '/ayuda' },
      { text: '🏠 Menú', callback_data: '/start' }
    ]
  ]
};

return [{
  json: {
    chatId: chatId,
    message: message,
    keyboard: keyboard
  }
}];

// Validate recipe detail parameters
const params = $input.first().json.params;
const chatId = $input.first().json.chatId;

if (!params.recipeId) {
  return [{
    json: {
      valid: false,
      chatId: chatId,
      message: '❌ Por favor indica el ID de la receta\n\n**Uso:** /receta [ID]\n\n**Ejemplo:**\n/receta 52940\n\n💡 Usa /buscar para encontrar recetas y sus IDs'
    }
  }];
}

return [{
  json: {
    valid: true,
    chatId: chatId,
    recipeId: params.recipeId
  }
}];

// Format recipe details
const response = $input.first().json;
const chatId = $('Validate Recipe').item.json.chatId;
const recipeId = $('Validate Recipe').item.json.recipeId;

if (response.error || !response.id) {
  return [{
    json: {
      chatId: chatId,
      message: `❌ No encontré la receta con ID: ${recipeId}\n\n${response.error || response.detail || ''}\n\n💡 Usa /buscar para encontrar recetas`
    }
  }];
}

const recipe = response;

// Build ingredients list
let ingredientsList = '';
if (recipe.ingredients && recipe.ingredients.length > 0) {
  ingredientsList = recipe.ingredients.slice(0, 15).map(ing => {
    const measure = ing.measure ? `${ing.measure} ` : '';
    return `• ${measure}${ing.name}`;
  }).join('\n');

  if (recipe.ingredients.length > 15) {
    ingredientsList += `\n... y ${recipe.ingredients.length - 15} más`;
  }
}

// Truncate instructions if too long
let instructions = recipe.instructions || 'No disponibles';
if (instructions.length > 800) {
  instructions = instructions.substring(0, 800) + '...\n\n[Instrucciones truncadas]';
}

let message = `🍳 **${recipe.name}**\n\n`;
message += `🏷 **Categoría:** ${recipe.category}\n`;
message += `🌍 **Cocina:** ${recipe.area}\n`;

if (recipe.tags && recipe.tags.length > 0) {
  message += `🏷 **Tags:** ${recipe.tags.join(', ')}\n`;
}

message += `\n📝 **Ingredientes:**\n${ingredientsList}\n`;
message += `\n👨‍🍳 **Instrucciones:**\n${instructions}`;

const keyboard = {
  inline_keyboard: [
    [
      { text: '⭐ Agregar a Favoritos', callback_data: `/favorito ${recipe.id} ${recipe.name.substring(0, 30)}` },
    ],
    [
      { text: '🔍 Buscar Otra', callback_data: '/ayuda' },
      { text: '🏠 Menú', callback_data: '/start' }
    ]
  ]
};

// If recipe has image, we'll send it separately
const hasImage = recipe.image_url && recipe.image_url.startsWith('http');

return [{
  json: {
    chatId: chatId,
    message: message,
    keyboard: keyboard,
    imageUrl: hasImage ? recipe.image_url : null,
    recipeName: recipe.name
  }
}];

// Format favorites list
const response = $input.first().json;
const chatId = $('Command Router').item.json.chatId;

if (response.error) {
  return [{
    json: {
      chatId: chatId,
      message: `❌ Error al obtener favoritos\n\nIntenta nuevamente más tarde.`
    }
  }];
}

const favorites = Array.isArray(response) ? response : [];

if (favorites.length === 0) {
  return [{
    json: {
      chatId: chatId,
      message: `⭐ **Tus Favoritos**\n\n😕 Aún no tienes recetas favoritas\n\n💡 Busca recetas con /buscar y agrégalas a favoritos\n\n📌 Puedes guardar hasta 10 recetas favoritas`,
      keyboard: {
        inline_keyboard: [
          [
            { text: '🔍 Buscar Recetas', callback_data: '/ayuda' },
            { text: '🍽 Recomendaciones', callback_data: '/recomendar' }
          ],
          [
            { text: '🏠 Menú Principal', callback_data: '/start' }
          ]
        ]
      }
    }
  }];
}

let message = `⭐ **Tus Recetas Favoritas (${favorites.length}/10)**\n\n`;

favorites.forEach((fav, index) => {
  message += `${index + 1}. **${fav.recipe_name}**\n`;
  message += `   🆔 ID: ${fav.recipe_id}\n`;
  if (fav.recipe_category) {
    message += `   🏷 ${fav.recipe_category}\n`;
  }
  message += `\n`;
});

message += `\n💡 Usa /receta [ID] para ver detalles`;
message += `\n💡 Usa /eliminar_favorito [ID] para quitar`;

// Create buttons for first 3 favorites
const favButtons = favorites.slice(0, 3).map(f => ({
  text: `📖 ${f.recipe_name.substring(0, 15)}...`,
  callback_data: `/receta ${f.recipe_id}`
}));

const keyboard = {
  inline_keyboard: [
    favButtons.slice(0, 2),
    [
      { text: '🔍 Buscar Más', callback_data: '/ayuda' },
      { text: '🏠 Menú', callback_data: '/start' }
    ]
  ]
};

return [{
  json: {
    chatId: chatId,
    message: message,
    keyboard: keyboard
  }
}];

// Validate add favorite parameters
const params = $input.first().json.params;
const chatId = $input.first().json.chatId;
const userId = $input.first().json.userId;

if (!params.recipeId) {
  return [{
    json: {
      valid: false,
      chatId: chatId,
      message: '❌ Por favor indica el ID de la receta\n\n**Uso:** /favorito [ID] [nombre]\n\n**Ejemplo:**\n/favorito 52940 Chicken Curry\n\n💡 Primero busca una receta con /buscar'
    }
  }];
}

return [{
  json: {
    valid: true,
    chatId: chatId,
    userId: userId,
    recipeId: params.recipeId,
    recipeName: params.recipeName || 'Receta ' + params.recipeId
  }
}];

// Format add favorite response
const response = $input.first().json;
const chatId = $('Validate Add Favorite').item.json.chatId;
const recipeName = $('Validate Add Favorite').item.json.recipeName;

if (response.error || response.success === false) {
  let errorMsg = response.error || response.detail || 'Error desconocido';
  if (errorMsg.includes('Limit') || errorMsg.includes('10')) {
    errorMsg = 'Has alcanzado el límite de 10 favoritos\n\n💡 Elimina alguno con /eliminar_favorito [ID]';
  }

  return [{
    json: {
      chatId: chatId,
      message: `❌ No se pudo agregar a favoritos\n\n${errorMsg}`
    }
  }];
}

return [{
  json: {
    chatId: chatId,
    message: `⭐ **¡Agregado a Favoritos!**\n\n📖 ${recipeName}\n\n💡 Usa /favoritos para ver todas tus recetas guardadas`,
    keyboard: {
      inline_keyboard: [
        [
          { text: '⭐ Ver Favoritos', callback_data: '/favoritos' },
          { text: '🔍 Buscar Más', callback_data: '/ayuda' }
        ],
        [
          { text: '🏠 Menú Principal', callback_data: '/start' }
        ]
      ]
    }
  }
}];

// Validate remove favorite parameters
const params = $input.first().json.params;
const chatId = $input.first().json.chatId;
const userId = $input.first().json.userId;

if (!params.recipeId) {
  return [{
    json: {
      valid: false,
      chatId: chatId,
      message: '❌ Por favor indica el ID de la receta a eliminar\n\n**Uso:** /eliminar_favorito [ID]\n\n**Ejemplo:**\n/eliminar_favorito 52940\n\n💡 Usa /favoritos para ver tus recetas guardadas'
    }
  }];
}

return [{
  json: {
    valid: true,
    chatId: chatId,
    userId: userId,
    recipeId: params.recipeId
  }
}];

// Format remove favorite response
const response = $input.first().json;
const chatId = $('Validate Remove Favorite').item.json.chatId;
const recipeId = $('Validate Remove Favorite').item.json.recipeId;

if (response.error || response.success === false) {
  return [{
    json: {
      chatId: chatId,
      message: `❌ No se pudo eliminar de favoritos\n\n${response.error || response.detail || 'Receta no encontrada en favoritos'}`
    }
  }];
}

return [{
  json: {
    chatId: chatId,
    message: `✅ **Eliminado de Favoritos**\n\n🆔 Receta ID: ${recipeId}\n\n💡 Usa /favoritos para ver tus recetas restantes`,
    keyboard: {
      inline_keyboard: [
        [
          { text: '⭐ Ver Favoritos', callback_data: '/favoritos' },
          { text: '🔍 Buscar Más', callback_data: '/ayuda' }
        ],
        [
          { text: '🏠 Menú Principal', callback_data: '/start' }
        ]
      ]
    }
  }
}];

// Handle dietary filter command
const params = $input.first().json.params;
const chatId = $input.first().json.chatId;
const userId = $input.first().json.userId;

const filterLabels = {
  'none': '🍽 Sin filtro',
  'vegetarian': '🥗 Vegetariano',
  'vegan': '🌱 Vegano',
  'gluten_free': '🌾 Sin Gluten'
};

// If no filter specified, show options
if (params.showOptions || !params.filter) {
  return [{
    json: {
      action: 'show_options',
      chatId: chatId,
      message: `🥗 **Filtro Dietético**\n\nSelecciona tu preferencia alimenticia:\n\n🍽 **Sin filtro** - Ver todas las recetas\n🥗 **Vegetariano** - Sin carne\n🌱 **Vegano** - Sin productos animales\n🌾 **Sin Gluten** - Apto para celíacos\n\n💡 El filtro se aplicará a todas tus búsquedas`,
      keyboard: {
        inline_keyboard: [
          [
            { text: '🍽 Sin Filtro', callback_data: '/filtro none' },
            { text: '🥗 Vegetariano', callback_data: '/filtro vegetarian' }
          ],
          [
            { text: '🌱 Vegano', callback_data: '/filtro vegan' },
            { text: '🌾 Sin Gluten', callback_data: '/filtro gluten_free' }
          ],
          [
            { text: '🏠 Menú Principal', callback_data: '/start' }
          ]
        ]
      }
    }
  }];
}

// Filter specified, update it
return [{
  json: {
    action: 'update_filter',
    chatId: chatId,
    userId: userId,
    filter: params.filter,
    filterLabel: filterLabels[params.filter] || params.filter
  }
}];

// Format filter update response
const response = $input.first().json;
const chatId = $('Handle Filter').item.json.chatId;
const filterLabel = $('Handle Filter').item.json.filterLabel;

if (response.error) {
  return [{
    json: {
      chatId: chatId,
      message: `❌ Error al actualizar filtro\n\n${response.error || 'Intenta nuevamente'}`
    }
  }];
}

return [{
  json: {
    chatId: chatId,
    message: `✅ **Filtro Actualizado**\n\n${filterLabel}\n\n💡 Este filtro se aplicará a tus próximas búsquedas\n\n¿Qué te gustaría hacer ahora?`,
    keyboard: {
      inline_keyboard: [
        [
          { text: '🔍 Buscar Recetas', callback_data: '/ayuda' },
          { text: '🍽 Recomendaciones', callback_data: '/recomendar' }
        ],
        [
          { text: '🏠 Menú Principal', callback_data: '/start' }
        ]
      ]
    }
  }
}];

// Format recommendations
const response = $input.first().json;
const chatId = $('Command Router').item.json.chatId;

if (response.error || !response.recipes) {
  return [{
    json: {
      chatId: chatId,
      message: `❌ Error al obtener recomendaciones\n\nIntenta nuevamente más tarde.`
    }
  }];
}

const recipes = response.recipes || [];

if (recipes.length === 0) {
  return [{
    json: {
      chatId: chatId,
      message: `🍽 **Recomendaciones**\n\n😕 No hay recomendaciones disponibles\n\nIntenta de nuevo más tarde`,
      keyboard: {
        inline_keyboard: [
          [
            { text: '🔍 Buscar Recetas', callback_data: '/ayuda' },
            { text: '🏠 Menú', callback_data: '/start' }
          ]
        ]
      }
    }
  }];
}

let message = `🍽 **¡Recomendaciones para ti!**\n\nBasadas en tus preferencias:\n\n`;

recipes.forEach((recipe, index) => {
  message += `${index + 1}. **${recipe.name}**\n`;
  message += `   🏷 ${recipe.category} | 🌍 ${recipe.area}\n`;
  message += `   🆔 ID: ${recipe.id}\n\n`;
});

message += `\n💡 Usa /receta [ID] para ver detalles`;
message += `\n💡 Usa /recomendar para más sugerencias`;

const recipeButtons = recipes.slice(0, 3).map(r => ({
  text: `📖 ${r.name.substring(0, 18)}...`,
  callback_data: `/receta ${r.id}`
}));

const keyboard = {
  inline_keyboard: [
    recipeButtons.slice(0, 2),
    [
      { text: '🔄 Más Sugerencias', callback_data: '/recomendar' },
      { text: '🏠 Menú', callback_data: '/start' }
    ]
  ]
};

return [{
  json: {
    chatId: chatId,
    message: message,
    keyboard: keyboard
  }
}];

// Handle unit conversion
const params = $input.first().json.params;
const chatId = $input.first().json.chatId;

// Conversion factors (to ml for volume, to g for weight)
const conversions = {
  // Volume -> ml
  'taza': { factor: 236.588, type: 'volume', to: 'ml' },
  'tazas': { factor: 236.588, type: 'volume', to: 'ml' },
  'cup': { factor: 236.588, type: 'volume', to: 'ml' },
  'cups': { factor: 236.588, type: 'volume', to: 'ml' },
  'cucharada': { factor: 14.787, type: 'volume', to: 'ml' },
  'cucharadas': { factor: 14.787, type: 'volume', to: 'ml' },
  'tbsp': { factor: 14.787, type: 'volume', to: 'ml' },
  'cucharadita': { factor: 4.929, type: 'volume', to: 'ml' },
  'cucharaditas': { factor: 4.929, type: 'volume', to: 'ml' },
  'tsp': { factor: 4.929, type: 'volume', to: 'ml' },
  'litro': { factor: 1000, type: 'volume', to: 'ml' },
  'litros': { factor: 1000, type: 'volume', to: 'ml' },
  'l': { factor: 1000, type: 'volume', to: 'ml' },
  'ml': { factor: 1, type: 'volume', to: 'ml' },
  'oz': { factor: 29.574, type: 'volume', to: 'ml' },
  'onza': { factor: 29.574, type: 'volume', to: 'ml' },
  'onzas': { factor: 29.574, type: 'volume', to: 'ml' },

  // Weight -> g
  'lb': { factor: 453.592, type: 'weight', to: 'g' },
  'libra': { factor: 453.592, type: 'weight', to: 'g' },
  'libras': { factor: 453.592, type: 'weight', to: 'g' },
  'kg': { factor: 1000, type: 'weight', to: 'g' },
  'kilogramo': { factor: 1000, type: 'weight', to: 'g' },
  'kilogramos': { factor: 1000, type: 'weight', to: 'g' },
  'g': { factor: 1, type: 'weight', to: 'g' },
  'gramo': { factor: 1, type: 'weight', to: 'g' },
  'gramos': { factor: 1, type: 'weight', to: 'g' }
};

if (!params.amount || !params.fromUnit) {
  return [{
    json: {
      chatId: chatId,
      message: `📏 **Convertidor de Medidas**\n\n**Uso:** /convertir [cantidad] [unidad] a [unidad]\n\n**Ejemplos:**\n• /convertir 2 tazas a ml\n• /convertir 500 g a lb\n• /convertir 1 litro a oz\n\n**Unidades soportadas:**\n\n📊 **Volumen:**\ntaza, cucharada, cucharadita, litro, ml, oz\n\n⚖️ **Peso:**\nlb, kg, g, gramo\n\n💡 Tip: También puedes escribir:\n"cup", "tbsp", "tsp" para inglés`
    }
  }];
}

const fromUnit = params.fromUnit.toLowerCase();
const toUnit = (params.toUnit || '').toLowerCase();
const amount = params.amount;

const fromConv = conversions[fromUnit];

if (!fromConv) {
  return [{
    json: {
      chatId: chatId,
      message: `❌ Unidad "${fromUnit}" no reconocida\n\n**Unidades válidas:**\n• Volumen: taza, cucharada, cucharadita, litro, ml, oz\n• Peso: lb, kg, g\n\n💡 Usa /convertir para ver ejemplos`
    }
  }];
}

// Convert to base unit first
const baseValue = amount * fromConv.factor;
const baseUnit = fromConv.to;

let result = '';
let resultValue = 0;
let resultUnit = '';

// If target unit specified and valid
if (toUnit && conversions[toUnit]) {
  const toConv = conversions[toUnit];
  if (toConv.type === fromConv.type) {
    resultValue = baseValue / toConv.factor;
    resultUnit = toUnit;
    result = `${amount} ${fromUnit} = **${resultValue.toFixed(2)} ${resultUnit}**`;
  } else {
    result = `❌ No se puede convertir ${fromConv.type} a ${toConv.type}`;
  }
} else {
  // Default conversion to base unit
  resultValue = baseValue;
  resultUnit = baseUnit;
  result = `${amount} ${fromUnit} = **${resultValue.toFixed(2)} ${resultUnit}**`;
}

const message = `📏 **Conversión**\n\n${result}\n\n💡 Usa /convertir para más conversiones`;

return [{
  json: {
    chatId: chatId,
    message: message,
    keyboard: {
      inline_keyboard: [
        [
          { text: '📏 Otra Conversión', callback_data: '/convertir' },
          { text: '🏠 Menú', callback_data: '/start' }
        ]
      ]
    }
  }
}];

